/// Screen centre (matches `set_screen_offset(160<<16, 120<<16)`). The
/// vertical centre and the vertical clip apron are per-view state for
/// split-screen: `set_view_rows` selects the 320x120 half being built.
static mut OFX_V: i32 = 160;
static mut OFY_V: i32 = 120;
static mut VX0_V: i32 = -1;
static mut VX1_V: i32 = 320;
static mut VY0_V: i32 = -1;
static mut VY1_V: i32 = 240;
#[inline(always)]
pub fn ofx() -> i32 {
    unsafe { OFX_V }
}
#[inline(always)]
pub fn ofy() -> i32 {
    unsafe { OFY_V }
}
#[inline(always)]
fn vx0() -> i32 {
    unsafe { VX0_V }
}
#[inline(always)]
fn vx1() -> i32 {
    unsafe { VX1_V }
}
#[inline(always)]
fn vy0() -> i32 {
    unsafe { VY0_V }
}
#[inline(always)]
fn vy1() -> i32 {
    unsafe { VY1_V }
}
/// Select the window of the current view: its screen centre and the
/// one-pixel apron the soft path clips against (x0-1 .. x0+w, y0-1 .. y0+h).
pub unsafe fn set_view_rect(x0: i32, y0: i32, w: i32, h: i32) {
    OFX_V = x0 + w / 2;
    OFY_V = y0 + h / 2;
    VX0_V = x0 - 1;
    VX1_V = x0 + w;
    VY0_V = y0 - 1;
    VY1_V = y0 + h;
}
